customCSS:
.t, .history { color: #57606a; }
.join { color: #116329; }
.part, .quit { color: #57606a; }
.kick, .error { color: #cf222e; }
.notice { color: #9a6700; }
.action { color: #8250df; }
.mode, .nick, .topic, .server { color: #1b7c83; }
.highlight { color: #24292f; background-color: #ddf4ff; border-left: 3px solid #8250df; padding-left: 8px; }
.reply { color: #57606a; border-left: 2px solid #0969da; padding-left: 6px; }
.oper { color: #ffffff; background-color: #9a6700; }
.reactions { color: #0969da; background-color: #f6f8fa; }
.card { background-color: #f6f8fa; border-color: #57606a; }
.card-title { color: #0969da; }
.card-desc { color: #57606a; }
.daychange { color: #57606a; border-color: #f6f8fa; }
